        let rounds: u32 = (iteration_limit(s.zoom) + 2047) / 2048
        let sx: u32 = __bitcast<i32, u32>(to_i32((s.res + 127.0) / 128.0))
        let sy: u32 = __bitcast<i32, u32>(to_i32((s.res + 255.0) / 256.0))
